insert into public.ascend_questions (id, subject, level, domain, skill, passage, data_table, question, choices, answer_index, accept, explanation, status, source, published_at) values
('rwl1e_001', 'rw', 1, 'Craft and Structure', 'Words in Context', 'Priya is known for being ____. When a classmate forgot his lunch, she gave him half of her sandwich and all of her grapes.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["generous", "selfish", "forgetful", "shy"]'::jsonb, 0, null, 'Sharing her lunch with a classmate who forgot his shows that Priya is generous.', 'published', 'import', now()),
('rwl1e_002', 'rw', 1, 'Craft and Structure', 'Words in Context', 'The museum displays ____ pottery that was made by hand more than four thousand years ago.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["modern", "ancient", "brand-new", "plastic"]'::jsonb, 1, null, 'Pottery that is thousands of years old is ancient.', 'published', 'import', now()),
('rwl1e_003', 'rw', 1, 'Craft and Structure', 'Words in Context', 'After running all 26 miles of the marathon, Jamal was so ____ that he fell asleep in the car on the way home.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["bored", "hungry", "energetic", "exhausted"]'::jsonb, 3, null, 'After running a marathon, someone who falls asleep right away is exhausted.', 'published', 'import', now()),
('rwl1e_004', 'rw', 1, 'Craft and Structure', 'Words in Context', 'Dad built a ____ picnic table out of thick oak boards. It can hold the whole family without even wobbling.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["sturdy", "flimsy", "tiny", "shiny"]'::jsonb, 0, null, 'A table that can hold heavy weight without wobbling is sturdy.', 'published', 'import', now()),
('rwl1e_005', 'rw', 1, 'Craft and Structure', 'Words in Context', 'The bird club was thrilled to spot a snowy owl. The ____ visitor had been seen in their town only three times in the last fifty years.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["noisy", "rare", "common", "ordinary"]'::jsonb, 1, null, 'A bird seen only a few times in fifty years is rare.', 'published', 'import', now()),
('rwl1e_006', 'rw', 1, 'Craft and Structure', 'Words in Context', 'Ms. Lopez says that Ben is a bright student. He learns new math ideas quickly and can solve puzzles that stump his classmates.', null, 'As used in the text, what does the word "bright" most nearly mean?', '["colorful", "shiny", "sunny", "smart"]'::jsonb, 3, null, 'A student who solves puzzles quickly and learns fast is smart.', 'published', 'import', now()),
('rwl1e_007', 'rw', 1, 'Craft and Structure', 'Words in Context', 'The farmer showed the children how to be ____ with the baby chicks, cupping each one softly in their hands.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["loud", "gentle", "careless", "rough"]'::jsonb, 1, null, 'Holding a baby chick carefully and softly is being gentle.', 'published', 'import', now()),
('rwl1e_008', 'rw', 1, 'Craft and Structure', 'Words in Context', 'Little Mia is very ____. She asks questions all day long, like why the sky is blue and how fish breathe underwater.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["uninterested", "sleepy", "curious", "angry"]'::jsonb, 2, null, 'Someone who keeps asking questions to learn more is curious.', 'published', 'import', now()),
('rwl1e_009', 'rw', 1, 'Craft and Structure', 'Text Structure and Purpose', 'Owls can swoop down on mice without making a sound. The edges of their wing feathers are soft and fringed, like a comb. These fringes break up the rush of air over the wings, which muffles the noise of flight.', null, 'Which choice best states the main purpose of the text?', '["To describe what owls eat", "To compare owls with eagles", "To argue that owls make good pets", "To explain how owls are able to fly quietly"]'::jsonb, 3, null, 'The text describes the owl''s soft, fringed feathers that let it fly without noise.', 'published', 'import', now()),
('rwl1e_010', 'rw', 1, 'Craft and Structure', 'Text Structure and Purpose', 'To make your own paper, first tear old newspaper into small pieces. Next, soak the pieces in warm water overnight. Then blend the soggy paper into a pulp. Finally, spread the pulp thinly on a screen and let it dry in the sun.', null, 'Which choice best describes the overall structure of the text?', '["It tells a story about a famous artist", "It describes the steps of a process in order", "It compares two different crafts", "It argues that paper should not be recycled"]'::jsonb, 1, null, 'The text gives the steps for making paper: tear, soak, blend, spread, dry.', 'published', 'import', now()),
('rwl1e_011', 'rw', 1, 'Craft and Structure', 'Text Structure and Purpose', 'The following text is from a short story.

Luis gripped the bat so tightly his knuckles turned white. Two strikes. He could hardly breathe. Then the ball came, and he swung—crack! As it sailed over the shortstop''s head, Luis felt a grin spread across his face.', null, 'Which choice best states the main purpose of the text?', '["To compare two baseball teams", "To explain the rules of baseball", "To describe a baseball stadium", "To show how a character''s feelings change during a game"]'::jsonb, 3, null, 'Luis starts out nervous and ends up proud after his hit.', 'published', 'import', now()),
('rwl1e_012', 'rw', 1, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
School uniforms help students focus on learning instead of on clothes. They also save families from arguing about what to wear each morning.

Text 2
Clothing is one of the ways young people show who they are. Requiring uniforms takes away that chance for self-expression.', null, 'Based on the texts, how would the author of Text 2 most likely respond to Text 1?', '["By saying that uniforms are too cheap", "By agreeing that uniforms should be required at every school", "By arguing that uniforms limit students'' ability to express themselves", "By claiming that students never get distracted"]'::jsonb, 2, null, 'Text 2 is concerned that uniforms take away a way for students to show who they are.', 'published', 'import', now()),
('rwl1e_013', 'rw', 1, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
House cats sleep for about 12 to 16 hours every day.

Text 2
Cats are hunters. In the wild, chasing prey takes short bursts of great energy, so cats rest for long periods to save their strength for the hunt.', null, 'Which choice best describes how the two texts are related?', '["Text 2 gives a reason for the behavior described in Text 1", "Both texts describe different animals", "Text 2 argues that Text 1 is false", "Text 1 explains Text 2''s main claim"]'::jsonb, 0, null, 'Text 1 says cats sleep a lot; Text 2 explains why.', 'published', 'import', now()),
('rwl1e_014', 'rw', 1, 'Information and Ideas', 'Central Ideas and Details', 'In Utah, a forest of about 47,000 aspen trees has a surprising secret. All of the trees grow from the same giant root system. Scientists consider this grove, called Pando, to be one single living thing, and one of the heaviest organisms on Earth.', null, 'Which choice best states the main idea of the text?', '["Pando is the tallest tree in the world", "A grove of aspen trees in Utah is actually a single living thing connected by one root system", "Aspen trees grow only in Utah", "Aspen trees lose their leaves in winter"]'::jsonb, 1, null, 'The text explains that all of Pando''s trunks share one root system, making it one organism.', 'published', 'import', now()),
('rwl1e_015', 'rw', 1, 'Information and Ideas', 'Central Ideas and Details', 'Roberto Clemente was a baseball star from Puerto Rico who also cared deeply about helping others. In December 1972, after a terrible earthquake struck Nicaragua, he gathered food and medical supplies for the survivors. He was flying with the supplies when his plane crashed into the sea. Today, baseball''s top award for community service is named after him.', null, 'According to the text, why was Roberto Clemente on the plane?', '["He was moving to Nicaragua", "He was learning to fly the plane", "He was bringing supplies to people hurt by an earthquake", "He was flying to a baseball game"]'::jsonb, 2, null, 'The text says he was delivering food and medicine to earthquake victims.', 'published', 'import', now()),
('rwl1e_016', 'rw', 1, 'Information and Ideas', 'Central Ideas and Details', 'The following text is from a short story.

Every Sunday, Mateo counted the hours until he could go to his grandmother''s house. He loved standing beside her in the warm kitchen, his hands covered in flour, as she taught him to fold the dough just right. He never stopped smiling the whole time.', null, 'Based on the text, how does Mateo feel about baking with his grandmother?', '["He enjoys it and looks forward to it", "He wishes he could bake alone", "He is afraid of the hot oven", "He thinks it is boring"]'::jsonb, 0, null, 'Mateo counts down the days and smiles while he works, showing he enjoys baking with her.', 'published', 'import', now()),
('rwl1e_017', 'rw', 1, 'Information and Ideas', 'Central Ideas and Details', 'Gardeners are often happy to see ladybugs. These small red beetles eat aphids, tiny insects that suck the juice out of plants. A single ladybug can eat thousands of aphids in its lifetime, protecting gardens without the need for chemical sprays.', null, 'Which choice best states the main idea of the text?', '["Ladybugs are harmful to gardens", "Gardeners should spray ladybugs with chemicals", "Ladybugs eat only leaves", "Ladybugs help gardeners by eating insects that harm plants"]'::jsonb, 3, null, 'The text explains that ladybugs eat aphids, which protects garden plants.', 'published', 'import', now()),
('rwl1e_018', 'rw', 1, 'Information and Ideas', 'Central Ideas and Details', 'When the Statue of Liberty, a gift from France, was completed in 1886, it was a shiny brownish color, like a new penny. The statue is covered in copper. Over about thirty years, the copper reacted with air and water, slowly forming a green coating that also protects the metal underneath.', null, 'According to the text, why is the Statue of Liberty green?', '["It was made from green stone", "Its copper covering changed color over time as it was exposed to air and water", "It is covered in plants", "It was painted green when it was built"]'::jsonb, 1, null, 'The text says the copper reacted with air and water and slowly turned green.', 'published', 'import', now()),
('rwl1e_019', 'rw', 1, 'Information and Ideas', 'Command of Evidence', 'Ms. Kim''s class voted on which pet to keep in their classroom. The class chose the hamster because ____', '{"h": ["Pet", "Votes"], "r": [["Hamster", "11"], ["Fish", "6"], ["Turtle", "4"], ["Rabbit", "7"]]}'::jsonb, 'Which choice most effectively uses data from the table to complete the statement?', '["the hamster received more votes than any other pet", "a total of four pets were in the vote", "the fish received 6 votes", "the turtle received fewer votes than the fish"]'::jsonb, 0, null, 'The statement is about the class''s choice, and the hamster got the most votes (11).', 'published', 'import', now()),
('rwl1e_020', 'rw', 1, 'Information and Ideas', 'Command of Evidence', 'In a short story, Nadia is described as an honest person.', null, 'Which quotation from the story best shows that Nadia is honest?', '["\"Nadia''s favorite color is purple.\"", "\"Nadia bought a bag of apples at the store.\"", "\"The store was crowded on Saturday morning.\"", "\"When the cashier gave her too much change, Nadia handed the extra five dollars back.\""]'::jsonb, 3, null, 'Returning money that isn''t hers shows honesty.', 'published', 'import', now()),
('rwl1e_021', 'rw', 1, 'Information and Ideas', 'Command of Evidence', 'A librarian claims that a program in which children read aloud to therapy dogs helps them become better readers.', null, 'Which finding would best support the librarian''s claim?', '["Some students are allergic to dogs", "The dogs in the program are all golden retrievers", "The program meets on Wednesday afternoons", "Students who read to the dogs each week improved their reading scores more than students who did not"]'::jsonb, 3, null, 'Only this finding shows that reading to dogs helped students read better.', 'published', 'import', now()),
('rwl1e_022', 'rw', 1, 'Information and Ideas', 'Command of Evidence', 'A student claims that sunflowers grew much taller in sunny spots than in shady spots. The table shows her results after four weeks.', '{"h": ["Plant", "Growth in sun (cm)", "Growth in shade (cm)"], "r": [["Sunflower", "40", "15"], ["Bean", "25", "12"]]}'::jsonb, 'Which choice most effectively uses data from the table to support the student''s claim?', '["Sunflowers grew 40 centimeters in sunny spots but only 15 centimeters in shady spots", "The plants were measured after four weeks", "Sunflowers and beans were both planted", "Beans grew 12 centimeters in the shade"]'::jsonb, 0, null, 'Only this choice compares sunflower growth in sun and shade.', 'published', 'import', now()),
('rwl1e_023', 'rw', 1, 'Information and Ideas', 'Command of Evidence', 'In a poem, the speaker describes feeling calm and peaceful while listening to the ocean.', null, 'Which quotation from the poem best illustrates the claim?', '["\"The parking lot was full by noon.\"", "\"We ate sandwiches for lunch.\"", "\"The sea rolls in like a quiet song, / and I could listen all day long.\"", "\"My brother brought a striped towel.\""]'::jsonb, 2, null, 'This quotation shows the speaker enjoying the peaceful sea.', 'published', 'import', now()),
('rwl1e_024', 'rw', 1, 'Information and Ideas', 'Inferences', 'In the morning, Grace found hoof-shaped tracks in the mud by the garden. The tops of her lettuce plants had been chewed off. She guessed that ____', null, 'Which choice most logically completes the text?', '["the yard was covered in snow", "someone had planted new flowers", "a deer had walked through the yard during the night", "it had not rained for months"]'::jsonb, 2, null, 'Fresh hoof prints and chewed plants are clues that a deer visited.', 'published', 'import', now()),
('rwl1e_025', 'rw', 1, 'Information and Ideas', 'Inferences', 'On Monday, Carlos filled the bird feeder to the top with seeds. All day, sparrows and finches crowded around it. By Tuesday morning, the feeder was empty. Carlos realized that ____', null, 'Which choice most logically completes the text?', '["no birds lived in the neighborhood", "the seeds were too big for the feeder", "the birds had eaten all the seeds", "the feeder had been broken by the wind"]'::jsonb, 2, null, 'A full feeder that is empty a day later, with many birds around, suggests the birds ate the seeds.', 'published', 'import', now()),
('rwl1e_026', 'rw', 1, 'Information and Ideas', 'Inferences', 'During the thunderstorm, there was a loud crack. Suddenly, the lights in Jada''s house went dark, the refrigerator stopped humming, and every window on the street turned black. Jada figured that ____', null, 'Which choice most logically completes the text?', '["the power had gone out in the neighborhood", "the family had bought a new television", "the storm had ended hours earlier", "it was the middle of the afternoon"]'::jsonb, 0, null, 'Every house going dark at once during a storm suggests a power outage.', 'published', 'import', now()),
('rwl1e_027', 'rw', 1, 'Information and Ideas', 'Inferences', 'After a big rainstorm, there was a large puddle on the playground. Over the next three hot, sunny days, the puddle got smaller and smaller until only a damp spot was left. This suggests that ____', null, 'Which choice most logically completes the text?', '["the sun had dried up much of the water", "more rain had fallen overnight", "the puddle had frozen solid", "someone had added water to the puddle"]'::jsonb, 0, null, 'On hot, sunny days, water evaporates, so the puddle shrank.', 'published', 'import', now()),
('rwl1e_028', 'rw', 1, 'Information and Ideas', 'Inferences', 'When the bus pulled into the school parking lot, the soccer players were cheering and singing. The captain held a shiny trophy over her head, and the coach was smiling. Watching from the window, Ellie guessed that ____', null, 'Which choice most logically completes the text?', '["the game had been canceled", "the team had probably won the game", "the players were too tired to celebrate", "the team had lost badly"]'::jsonb, 1, null, 'Cheering, a trophy, and players dancing are signs of a win.', 'published', 'import', now()),
('rwl1e_029', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'Last summer, my family drove to the ____ built a huge sandcastle with a moat around it.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["beach, we", "beach and, we", "beach we", "beach. We"]'::jsonb, 3, null, 'These are two complete sentences, so a period separates them.', 'published', 'import', now()),
('rwl1e_030', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'Pancakes need only a few simple ____ eggs, milk, and a pinch of salt.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["ingredients: flour,", "ingredients; flour,", "ingredients, flour:", "ingredients flour,"]'::jsonb, 0, null, 'A colon after a complete sentence introduces a list.', 'published', 'import', now()),
('rwl1e_031', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'Franklin ____ 32nd president of the United States, was elected four times.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Roosevelt; the", "Roosevelt, the", "Roosevelt the", "Roosevelt. The"]'::jsonb, 1, null, 'The phrase "the 32nd president of the United States" describes Roosevelt and is set off by commas.', 'published', 'import', now()),
('rwl1e_032', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'The hikers were ____ they kept climbing until they reached the top of the mountain.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["tired but,", "tired, but", "tired; but,", "tired. But,"]'::jsonb, 1, null, 'A comma comes before "but" when it joins two complete sentences.', 'published', 'import', now()),
('rwl1e_033', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'The field was soaked after the morning ____ the game was moved to the indoor gym.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["rain", "rain:", "rain,", "rain;"]'::jsonb, 3, null, 'A semicolon joins two complete sentences without a joining word.', 'published', 'import', now()),
('rwl1e_034', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'The frogs in the ____ croak loudly every night in the spring.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["pond,", "pond;", "pond", "pond:"]'::jsonb, 2, null, 'No punctuation belongs between the subject "The frogs in the pond" and the verb "croak."', 'published', 'import', now()),
('rwl1e_035', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'The box of crayons on the art table ____ almost empty.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["is", "are", "were", "have been"]'::jsonb, 0, null, 'The subject "the box" is singular, so the verb is "is."', 'published', 'import', now()),
('rwl1e_036', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'The students packed ____ backpacks before the field trip to the science museum.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["her", "its", "his", "their"]'::jsonb, 3, null, '"The students" is plural, so the pronoun is "their."', 'published', 'import', now()),
('rwl1e_037', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'Next summer, my cousins ____ us in Chicago for two weeks.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["visits", "visited", "has visited", "will visit"]'::jsonb, 3, null, '"Next summer" tells us the action is in the future.', 'published', 'import', now()),
('rwl1e_038', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'A flock of ____ flew over the lake in a V shape.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["gooses", "geeses", "geese", "goose''s"]'::jsonb, 2, null, 'The plural of "goose" is "geese."', 'published', 'import', now()),
('rwl1e_039', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'The little ____ bike had pink streamers on the handlebars.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["girl''s", "girls''", "girls", "girles"]'::jsonb, 0, null, 'The bike belongs to one girl, so the singular possessive "girl''s" is correct.', 'published', 'import', now()),
('rwl1e_040', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'Of the two sunflowers in the garden, the one by the fence is ____.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["most tallest", "taller", "more tall", "tallest"]'::jsonb, 1, null, 'Comparing two things uses "taller."', 'published', 'import', now()),
('rwl1e_041', 'rw', 1, 'Expression of Ideas', 'Transitions', 'Most spiders spin webs to catch their food. ____ wolf spiders chase down their prey on the ground.', null, 'Which choice completes the text with the most logical transition?', '["Therefore,", "Also,", "However,", "For example,"]'::jsonb, 2, null, 'The second sentence contrasts with the first.', 'published', 'import', now()),
('rwl1e_042', 'rw', 1, 'Expression of Ideas', 'Transitions', 'To wash a dog, first wet its fur with warm water. ____ rub in the shampoo and rinse it out.', null, 'Which choice completes the text with the most logical transition?', '["Next,", "In contrast,", "However,", "For example,"]'::jsonb, 0, null, 'The steps happen in order.', 'published', 'import', now()),
('rwl1e_043', 'rw', 1, 'Expression of Ideas', 'Transitions', 'Some animals are active mostly at night. ____ raccoons sleep during the day and search for food after dark.', null, 'Which choice completes the text with the most logical transition?', '["Instead,", "For example,", "Finally,", "However,"]'::jsonb, 1, null, 'The second sentence gives an example of a nocturnal animal.', 'published', 'import', now()),
('rwl1e_044', 'rw', 1, 'Expression of Ideas', 'Transitions', 'Ava practiced the violin for an hour every day. ____ she played her solo perfectly at the spring concert.', null, 'Which choice completes the text with the most logical transition?', '["As a result,", "However,", "Meanwhile,", "For instance,"]'::jsonb, 0, null, 'Practicing every day led to Ava playing well.', 'published', 'import', now()),
('rwl1e_045', 'rw', 1, 'Expression of Ideas', 'Transitions', 'Riding a bike is good exercise. ____ it causes no air pollution.', null, 'Which choice completes the text with the most logical transition?', '["In contrast,", "However,", "Also,", "Instead,"]'::jsonb, 2, null, 'The second sentence adds another benefit of riding bikes.', 'published', 'import', now()),
('rwl1e_046', 'rw', 1, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Sequoyah was born around 1770 in Tennessee.
• He was a silversmith.
• He created a writing system for the Cherokee language.
• His system used a different symbol for each syllable.
• It was completed in 1821.', null, 'The student wants to explain what Sequoyah created. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Sequoyah lived in Tennessee.", "Sequoyah was born around 1770.", "Sequoyah created a writing system for the Cherokee language that used a symbol for each syllable.", "Sequoyah was a silversmith."]'::jsonb, 2, null, 'Only this choice describes what he created.', 'published', 'import', now()),
('rwl1e_047', 'rw', 1, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Hot air balloons rise because hot air is lighter than cool air.
• Two French brothers built one of the first hot air balloons.
• In 1783, they tested it in France.
• The first passengers were a sheep, a duck, and a rooster.
• All three animals landed safely.', null, 'The student wants to describe the first hot air balloon passengers. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The balloon was built by two brothers.", "Hot air balloons rise because hot air is lighter than cool air.", "The first passengers in a hot air balloon were a sheep, a duck, and a rooster.", "The flight took place in France in 1783."]'::jsonb, 2, null, 'Only this choice tells who the first passengers were.', 'published', 'import', now()),
('rwl1e_048', 'rw', 1, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Venus and Mars are Earth''s nearest planet neighbors.
• Venus is extremely hot, about 870°F.
• Mars is very cold, often below −80°F.
• Venus has no moons.
• Mars has two small moons.', null, 'The student wants to show a difference between Venus and Mars. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Venus and Mars are both near Earth.", "Venus and Mars are both planets.", "Mars has two small moons.", "Venus is extremely hot, while Mars is very cold."]'::jsonb, 3, null, 'Only this choice states a difference between the planets.', 'published', 'import', now()),
('rwl1e_049', 'rw', 1, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The Golden Gate Bridge in San Francisco opened in 1937.
• It is about 1.7 miles long.
• Its color is called "International Orange."
• The color was chosen so the bridge would be easy to see in fog.
• Painters touch up the bridge all year long.', null, 'The student wants to explain why the Golden Gate Bridge is painted orange. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The Golden Gate Bridge is about 1.7 miles long.", "The Golden Gate Bridge is painted bright orange so that it is easy to see in fog.", "Painters work on the Golden Gate Bridge all year.", "The Golden Gate Bridge opened in 1937."]'::jsonb, 1, null, 'Only this choice gives the reason for the color.', 'published', 'import', now()),
('rwl2f_001', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Gas prices tend to ____ throughout the year, rising in the busy summer travel season and falling again in the winter.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["multiply", "fluctuate", "vanish", "stabilize"]'::jsonb, 1, null, 'Prices that go up and down from week to week fluctuate.', 'published', 'import', now()),
('rwl2f_002', 'rw', 2, 'Craft and Structure', 'Words in Context', 'For early mountain climbers, the lack of oxygen at high altitudes was a serious ____, leaving many too weak to reach the summit.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["advantage", "shortcut", "reward", "obstacle"]'::jsonb, 3, null, 'Something that blocks progress is an obstacle.', 'published', 'import', now()),
('rwl2f_003', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Many wildflowers ____ in poor, rocky soil where other plants struggle to survive, spreading quickly across hillsides each spring.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["disappear", "thrive", "struggle", "hibernate"]'::jsonb, 1, null, 'Plants that grow well in poor soil thrive there.', 'published', 'import', now()),
('rwl2f_004', 'rw', 2, 'Craft and Structure', 'Words in Context', 'When a classmate claimed he had trained his goldfish to do tricks, Jada was ____. She wanted to see it for herself before believing it.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["careless", "skeptical", "delighted", "confident"]'::jsonb, 1, null, 'Doubting a claim until seeing proof is being skeptical.', 'published', 'import', now()),
('rwl2f_005', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Dr. Okafor has worked in the field of marine biology for twenty years, studying how coral reefs recover after storms.', null, 'As used in the text, what does the word "field" most nearly mean?', '["sports area", "open land", "crop", "area of study"]'::jsonb, 3, null, 'Marine biology is a subject that scientists study, so "field" means area of study.', 'published', 'import', now()),
('rwl2f_006', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Hiking boots must be ____: a good pair can last for years of hiking over sharp rocks and through muddy streams.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["durable", "fragile", "expensive", "colorful"]'::jsonb, 0, null, 'Boots that last for years of hard use are durable.', 'published', 'import', now()),
('rwl2f_007', 'rw', 2, 'Craft and Structure', 'Words in Context', 'In late summer, berries are so ____ in the forest that bears can eat tens of thousands of them in a single day.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["poisonous", "scarce", "expensive", "abundant"]'::jsonb, 3, null, 'Food that is plentiful is abundant.', 'published', 'import', now()),
('rwl2f_008', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Because many students were confused by the homework instructions, the teacher wrote a short note to ____ what each question was asking.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["repeat", "complicate", "ignore", "clarify"]'::jsonb, 3, null, 'Making something easier to understand is to clarify it.', 'published', 'import', now()),
('rwl2f_009', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'Long before chocolate bars existed, people in Mesoamerica ground cacao beans into a bitter, frothy drink, sometimes flavored with chili peppers. After cacao reached Europe in the 1500s, cooks began adding sugar. Centuries later, new machines made it possible to press chocolate into the solid, sweet bars eaten today.', null, 'Which choice best states the main purpose of the text?', '["To compare different brands of chocolate", "To explain how chocolate changed from a bitter drink to a sweet treat", "To describe how cacao trees grow", "To argue that chocolate is a healthy food"]'::jsonb, 1, null, 'The text traces chocolate''s history from a bitter Mesoamerican drink to sweetened chocolate.', 'published', 'import', now()),
('rwl2f_010', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'Thousands of pieces of old satellites and rocket parts now circle Earth. This "space junk" moves so fast that even a small bolt can damage a working satellite. Engineers have proposed several fixes, including giant nets to catch debris and small spacecraft that would push old satellites down into the atmosphere to burn up.', null, 'Which choice best describes the overall structure of the text?', '["It describes a problem and then presents possible solutions", "It compares two planets", "It tells the life story of an astronaut", "It explains how rockets are built"]'::jsonb, 0, null, 'The text describes space junk as a problem and then describes ideas for removing it.', 'published', 'import', now()),
('rwl2f_011', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'Every European eel is born in the Sargasso Sea, a region of the Atlantic Ocean. This is surprising because adult eels spend most of their lives in rivers and lakes thousands of miles away in Europe. Near the end of their lives, they swim all the way back to the Sargasso Sea to lay their eggs.', null, 'Which choice best describes the function of the second sentence in the overall structure of the text?', '["It gives the date of the journey", "It argues that eels should be protected", "It introduces a different animal", "It explains why the first trip mentioned is surprising"]'::jsonb, 3, null, 'The second sentence points out that eels live in rivers, which makes their ocean journey remarkable.', 'published', 'import', now()),
('rwl2f_012', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'The following text is from a short story.

Nora hammered the last nail and stepped back. The birdhouse leaned to one side, and the roof had a gap wide enough to fit a finger through. "You rushed the measuring," her father said gently. Nora sighed, picked up the ruler, and started again—slowly this time.', null, 'Which choice best states the main purpose of the text?', '["To show a character learning that a skill takes patience", "To describe how to build a birdhouse", "To explain why the character''s father is a carpenter", "To compare two kinds of wood"]'::jsonb, 0, null, 'Nora wants to finish quickly, but her father''s advice and the crooked birdhouse teach her to slow down.', 'published', 'import', now()),
('rwl2f_013', 'rw', 2, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
For many years, scientists assumed that dinosaurs were cold-blooded, like modern lizards. Cold-blooded animals depend on the sun for warmth and are often slow-moving.

Text 2
By studying growth rings in fossil bones, some scientists have found that many dinosaurs grew very quickly, more like birds and mammals than lizards. Because rapid growth requires a lot of energy, these scientists argue that many dinosaurs were probably warm-blooded.', null, 'Based on the texts, how would the scientists described in Text 2 most likely respond to Text 1?', '["By arguing that dinosaur bones cannot be studied", "By arguing that fast bone growth suggests that some dinosaurs were warm-blooded", "By claiming that dinosaurs were closely related to fish", "By agreeing that all dinosaurs were cold-blooded"]'::jsonb, 1, null, 'Text 2''s scientists think fast growth points to warm-bloodedness, which challenges Text 1.', 'published', 'import', now()),
('rwl2f_014', 'rw', 2, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
Supporters of daylight saving time say that moving clocks ahead one hour in spring saves energy, because people need fewer lights on long summer evenings.

Text 2
Research on daylight saving time has produced mixed results. Several studies have found that any savings on lighting are small and may be canceled out by greater use of air conditioning in the warm evening hours.', null, 'Based on the texts, how would the author of Text 2 most likely respond to Text 1?', '["By claiming that people prefer darker evenings", "By agreeing that daylight saving time saves a great deal of energy", "By arguing that clocks should be set back two hours", "By pointing out that studies have found the energy savings to be small or nonexistent"]'::jsonb, 3, null, 'Text 2 cites studies that question the energy savings Text 1 claims.', 'published', 'import', now()),
('rwl2f_015', 'rw', 2, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
Students who learn a musical instrument practice paying attention, remembering patterns, and setting goals. These skills can help them in other subjects as well.

Text 2
Playing in a school band teaches teamwork. Band members must listen closely to one another, and many students say that band is where they made their closest friends.', null, 'Based on the texts, both authors would most likely agree that', '["learning to play an instrument can benefit young people", "students should practice music for at least three hours a day", "music lessons are too expensive for most families", "only band classes help students make friends"]'::jsonb, 0, null, 'Text 1 points to focus and memory; Text 2 points to teamwork and friendship. Both see benefits.', 'published', 'import', now()),
('rwl2f_016', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'In 1862, Robert Smalls, an enslaved man who worked as a pilot on the Confederate ship Planter, made a daring escape. Before dawn, while the ship''s officers were ashore, he steered the Planter past several Confederate forts in Charleston Harbor and delivered it to the Union navy, freeing himself, his family, and the crew. Smalls later served five terms in the U.S. Congress.', null, 'Which choice best states the main idea of the text?', '["Smalls used his skill as a ship''s pilot to win freedom for himself and others and later became a lawmaker", "Smalls was an admiral in the Union navy", "Smalls built the Planter himself", "Smalls sailed the ship alone"]'::jsonb, 0, null, 'The text describes how Smalls piloted the ship to freedom and later served in Congress.', 'published', 'import', now()),
('rwl2f_017', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'On some beaches, breaking waves glow bright blue at night. The light comes from tiny plankton called dinoflagellates. When the water around them is stirred up—by a wave, a swimmer, or a passing boat—they give off a flash of light.', null, 'According to the text, what causes some ocean waves to glow at night?', '["The water is heated by the sun during the day", "Lights from nearby cities shine on the water", "Tiny living things in the water give off light when they are disturbed", "Moonlight reflects off the foam"]'::jsonb, 2, null, 'The text says that plankton light up when waves move them.', 'published', 'import', now()),
('rwl2f_018', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'In 1974, farmers digging a well in China struck pieces of clay. Archaeologists soon uncovered thousands of life-size clay soldiers, each with its own face, arranged in rows near the tomb of Qin Shi Huang, China''s first emperor. The figures had been buried more than two thousand years earlier, apparently to guard the emperor in the afterlife.', null, 'Which choice best states the main idea of the text?', '["The emperor was buried alone without any objects", "Farmers digging a well uncovered a huge collection of clay soldiers made for an ancient emperor", "The soldiers were made of solid gold", "The farmers built the clay soldiers themselves"]'::jsonb, 1, null, 'The text describes the farmers'' discovery of the Terracotta Army.', 'published', 'import', now()),
('rwl2f_019', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'The following text is from a short story.

Whenever the power went out, the grandchildren gathered around Grandpa Teo''s chair. By candlelight, he told stories about the fishing village where he grew up—the storms, the boats, the night the whole town searched for a lost goat. When the lights came back on, the children always begged him to finish one more.', null, 'Based on the text, what is true about Grandpa Teo?', '["He is a famous writer", "He shares his memories through stories that his grandchildren treasure", "He doesn''t like to talk about the past", "He has just moved to the city"]'::jsonb, 1, null, 'The grandchildren gather around and beg for more stories, showing they love hearing him.', 'published', 'import', now()),
('rwl2f_020', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'Many fruits, nuts, and vegetables depend on bees. As bees move from flower to flower collecting nectar, they carry pollen that crops such as almonds, apples, and blueberries need to make seeds and fruit. Without bees, farmers would harvest far less of these foods.', null, 'According to the text, why are bees important to farmers?', '["They make the soil richer", "They keep birds away from the fields", "They eat insects that damage crops", "They carry pollen between flowers, which many crops need to produce food"]'::jsonb, 3, null, 'The text explains that bees pollinate crops such as almonds and apples.', 'published', 'import', now()),
('rwl2f_021', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'A student claims that switching to LED light bulbs reduced the share of a school''s electricity used for lighting.', '{"h": ["Use", "2022 (%)", "2024 (%)"], "r": [["Lighting", "30", "18"], ["Heating", "40", "40"], ["Computers", "15", "20"], ["Other", "15", "22"]]}'::jsonb, 'Which choice most effectively uses data from the table to support the claim?', '["The school used electricity for four main purposes", "Lighting use fell from 30 percent to 18 percent of the school''s electricity after the switch to LED bulbs", "Computers used 20 percent of the electricity in 2024", "Heating used 40 percent of the electricity both years"]'::jsonb, 1, null, 'The claim is about LED bulbs reducing lighting use; this choice shows that drop.', 'published', 'import', now()),
('rwl2f_022', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'In a novel, Wren is described as an extremely cautious hiker.', null, 'Which quotation from the novel most effectively illustrates the claim?', '["\"The trail wound through a pine forest.\"", "\"Wren''s friends were already at the lake.\"", "\"Wren wore a green jacket and a wool hat.\"", "\"Wren checked the map, then checked it again, and still refused to take a single step until she had counted every trail marker.\""]'::jsonb, 3, null, 'Checking the map repeatedly and counting markers shows how cautious Wren is.', 'published', 'import', now()),
('rwl2f_023', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'A student hypothesizes that young plants grow toward the direction of light.', null, 'Which finding, if true, would most directly support the student''s hypothesis?', '["The seedlings needed water every other day", "Some seedlings grew taller than others", "Seedlings placed beside a sunny window bent toward the glass within three days, while seedlings in an evenly lit room grew straight up", "The seedlings were planted in the same kind of soil"]'::jsonb, 2, null, 'Only this finding shows seedlings bending toward light.', 'published', 'import', now()),
('rwl2f_024', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'Organizers of a city''s book festival say the event has grown steadily since it began. The table shows that ____', '{"h": ["Year", "Attendance"], "r": [["2021", "1,200"], ["2022", "2,100"], ["2023", "2,800"], ["2024", "3,500"]]}'::jsonb, 'Which choice most effectively uses data from the table to complete the statement?', '["the festival was held four times", "attendance was 2,100 in 2022", "attendance rose each year, from 1,200 in 2021 to 3,500 in 2024", "attendance in 2023 was greater than in 2022"]'::jsonb, 2, null, 'Only this choice shows the steady growth across all four years.', 'published', 'import', now()),
('rwl2f_025', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'A library director claims that adding a coffee cart in the lobby last fall caused a 15 percent increase in library visits over the winter.', null, 'Which finding, if true, would most directly weaken the claim?', '["Most visitors buy coffee in the morning", "The library''s visits rose by the same amount during the same months in years before the coffee cart was added", "The coffee cart sells muffins as well as coffee", "The library is open seven days a week"]'::jsonb, 1, null, 'If visits rose just as much in earlier years, the increase was probably seasonal, not caused by the coffee cart.', 'published', 'import', now()),
('rwl2f_026', 'rw', 2, 'Information and Ideas', 'Inferences', 'Hikers on a mountain thousands of feet above sea level found rocks filled with fossils of seashells and small sea creatures. Geologists explain this discovery by suggesting that ____', null, 'Which choice most logically completes the text?', '["the area was once covered by the ocean", "people once lived on the mountain", "the mountain was formed by a volcano", "fish can live at high altitudes"]'::jsonb, 0, null, 'Seashell fossils high on a mountain suggest the rock formed under the sea.', 'published', 'import', now()),
('rwl2f_027', 'rw', 2, 'Information and Ideas', 'Inferences', 'Trees add one ring each year, and the ring is wider in years when the tree grows more. A tree cut down in 2020 had several very narrow rings from the years 1930 to 1936. Records show that those years were unusually dry in the region. This suggests that ____', null, 'Which choice most logically completes the text?', '["the tree was cut down that year", "the tree grew fastest during the drought", "the tree grew slowly during a period of dry years", "the rings are not related to weather"]'::jsonb, 2, null, 'Narrow rings matched dry years, so the tree grew slowly then.', 'published', 'import', now()),
('rwl2f_028', 'rw', 2, 'Information and Ideas', 'Inferences', 'In the year before a city added a countdown crosswalk signal at a busy intersection, there were 14 accidents involving pedestrians. In the year after, there were 5, even though about the same number of people crossed there. This suggests that ____', null, 'Which choice most logically completes the text?', '["more cars began using the intersection", "the new crosswalk signal may have made the intersection safer for pedestrians", "pedestrians stopped using the intersection", "the signal caused more accidents"]'::jsonb, 1, null, 'Accidents dropped after the signal was added while foot traffic stayed the same.', 'published', 'import', now()),
('rwl2f_029', 'rw', 2, 'Information and Ideas', 'Inferences', 'A letter found in an old trunk is signed only "M." and has no date. In the letter, the writer mentions talking to a cousin "on the telephone last Sunday." Since the telephone was invented in 1876, historians can conclude that ____', null, 'Which choice most logically completes the text?', '["the letter was written by someone who lived after the telephone was invented", "the author had never heard of telephones", "the letter was written in 1850", "the letter was written by a famous inventor"]'::jsonb, 0, null, 'Mentioning a telephone call means the writer lived after telephones existed.', 'published', 'import', now()),
('rwl2f_030', 'rw', 2, 'Information and Ideas', 'Inferences', 'Researchers counted bats flying along two streets the same distance from a roost. One street had bright streetlights; the other''s lights had been turned off for the study. Many more bats flew along the dark street. This finding suggests that ____', null, 'Which choice most logically completes the text?', '["bats prefer to hunt near bright lights", "the streetlights attract more insects to the dark streets", "the bats may be avoiding light rather than simply staying near their roost", "bats never leave their roost"]'::jsonb, 2, null, 'Bats used the darkened street but avoided the lit one, even at the same distance, so light seems to keep them away.', 'published', 'import', now()),
('rwl2f_031', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'Saturn is less dense than ____ a bathtub large enough to hold it existed, the planet would float.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["water; if", "water, if", "water and if", "water if"]'::jsonb, 0, null, 'Two complete sentences can be joined with a semicolon.', 'published', 'import', now()),
('rwl2f_032', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'Sonia ____ first Hispanic justice on the U.S. Supreme Court, joined the Court in 2009.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Sotomayor. The", "Sotomayor; the", "Sotomayor the", "Sotomayor, the"]'::jsonb, 3, null, '"the first Hispanic justice on the U.S. Supreme Court" describes Sotomayor and is set off by commas.', 'published', 'import', now()),
('rwl2f_033', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'The Taj Mahal is famous for two main ____ is one of the most beautiful buildings in the world, and it was built as a memorial to an emperor''s wife.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["reasons; and it", "reasons it", "reasons: it", "reasons, it"]'::jsonb, 2, null, 'A colon after a complete sentence introduces the explanation that follows.', 'published', 'import', now()),
('rwl2f_034', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'The Komodo dragon is the world''s largest ____ can grow up to ten feet long.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["lizard, which", "lizard; which", "lizard which", "lizard. Which"]'::jsonb, 0, null, '"which can grow ten feet long" adds extra information and is set off with a comma.', 'published', 'import', now()),
('rwl2f_035', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'The glowing lights in the northern ____ are called the aurora borealis.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["skies:", "skies,", "skies", "skies;"]'::jsonb, 2, null, 'No punctuation belongs between the subject "The glowing lights in the northern skies" and the verb "are."', 'published', 'import', now()),
('rwl2f_036', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'The tomatoes that grew along the back fence of the community garden ____ ripe by the end of July.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["has been", "was", "were", "is"]'::jsonb, 2, null, 'The subject "the tomatoes" is plural and the event is in the past, so "were" is correct.', 'published', 'import', now()),
('rwl2f_037', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'The company announced that ____ new factory will open next year.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["his", "their", "its", "it''s"]'::jsonb, 2, null, '"The company" is singular, so the possessive pronoun is "its."', 'published', 'import', now()),
('rwl2f_038', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'By the time Ivan reached the station, the train ____.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["already leaves", "had already left", "will already leave", "is already leaving"]'::jsonb, 1, null, 'The train left before Ivan arrived, an earlier past event, so the past perfect is needed.', 'published', 'import', now()),
('rwl2f_039', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'Looking through her binoculars, ____', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["she spotted a hawk circling above the field.", "a hawk was spotted circling above the field.", "the field had a hawk circling above it.", "circling above the field was a hawk."]'::jsonb, 0, null, 'The opening phrase describes who was looking through the binoculars, so "she" must come right after it.', 'published', 'import', now()),
('rwl2f_040', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'Both ____ uniforms were covered in mud by the end of the rainy game.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["teams''", "teams", "teams''s", "team''s"]'::jsonb, 0, null, 'The uniforms belong to both teams, so the plural possessive "teams''" is correct.', 'published', 'import', now()),
('rwl2f_041', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Snakes cannot chew their food. ____ they swallow their prey whole, stretching their jaws wide.', null, 'Which choice completes the text with the most logical transition?', '["Similarly,", "As a result,", "Instead,", "For example,"]'::jsonb, 2, null, 'The second sentence tells what the snake does in place of chewing.', 'published', 'import', now()),
('rwl2f_042', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Chameleons can change their skin color to blend in with their surroundings. ____ some octopuses can change color in less than a second to hide from predators.', null, 'Which choice completes the text with the most logical transition?', '["Finally,", "However,", "Similarly,", "Instead,"]'::jsonb, 2, null, 'Both sentences describe animals that use the same trick.', 'published', 'import', now()),
('rwl2f_043', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Teenagers need about nine hours of sleep each night to stay healthy. ____ doctors advise them to avoid screens late in the evening.', null, 'Which choice completes the text with the most logical transition?', '["However,", "Therefore,", "For example,", "Meanwhile,"]'::jsonb, 1, null, 'Getting more sleep is a conclusion based on the first sentence.', 'published', 'import', now()),
('rwl2f_044', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Rosa began her career as a science teacher at a small rural school. ____ she became the principal of the largest high school in the state.', null, 'Which choice completes the text with the most logical transition?', '["Later,", "For instance,", "Similarly,", "In contrast,"]'::jsonb, 0, null, 'The events are in time order: first a teacher, then a principal.', 'published', 'import', now()),
('rwl2f_045', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Cheetahs are extremely fast runners. ____ they can go from standing still to 60 miles per hour in about three seconds.', null, 'Which choice completes the text with the most logical transition?', '["Nevertheless,", "However,", "Instead,", "In fact,"]'::jsonb, 3, null, 'The second sentence strengthens the first with a striking detail.', 'published', 'import', now()),
('rwl2f_046', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The Komodo dragon is a kind of lizard.
• It lives on a few islands in Indonesia.
• It can grow up to ten feet long.
• It can weigh more than 150 pounds.
• It eats deer and wild pigs.', null, 'The student wants to emphasize the size of the Komodo dragon. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The Komodo dragon can grow up to ten feet long and weigh more than 150 pounds.", "The Komodo dragon lives on a few islands in Indonesia.", "The Komodo dragon eats deer and wild pigs.", "The Komodo dragon is a kind of lizard."]'::jsonb, 0, null, 'Only this choice gives the dragon''s length and weight.', 'published', 'import', now()),
('rwl2f_047', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The northern lights are also called the aurora borealis.
• They are often green, but can also be pink or purple.
• They happen when particles from the Sun strike gases high in Earth''s atmosphere.
• The gases glow when they are struck.
• They can be seen in places such as Alaska and Norway.', null, 'The student wants to explain what causes the northern lights. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The northern lights are often green.", "The northern lights are also called the aurora borealis.", "The northern lights appear when particles from the Sun strike gases high in Earth''s atmosphere, making them glow.", "The northern lights can be seen in Alaska and Norway."]'::jsonb, 2, null, 'Only this choice explains the cause.', 'published', 'import', now()),
('rwl2f_048', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Wilma Rudolph was born in Tennessee in 1940.
• As a child, she had polio and wore a leg brace.
• She competed at the 1960 Olympics in Rome.
• She won three gold medals in track.
• She later became a teacher and coach.', null, 'The student wants to describe Wilma Rudolph''s achievement at the 1960 Olympics. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["As a child, Wilma Rudolph had polio and wore a leg brace.", "Wilma Rudolph later became a teacher and coach.", "Wilma Rudolph was born in Tennessee in 1940.", "At the 1960 Olympics in Rome, Wilma Rudolph won three gold medals in track."]'::jsonb, 3, null, 'Only this choice describes what she did at the 1960 Olympics.', 'published', 'import', now()),
('rwl2f_049', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The Taj Mahal is in Agra, India.
• It is made of white marble.
• The emperor Shah Jahan ordered it built.
• It was a memorial to his wife, Mumtaz Mahal.
• It took about twenty years to build.', null, 'The student wants to explain why the Taj Mahal was built. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The Taj Mahal is made of white marble.", "The Taj Mahal took about twenty years to build.", "The Taj Mahal is in Agra, India.", "The emperor Shah Jahan built the Taj Mahal as a memorial to his wife, Mumtaz Mahal."]'::jsonb, 3, null, 'Only this choice explains the reason it was built.', 'published', 'import', now()),
('rwl3e_001', 'rw', 3, 'Craft and Structure', 'Words in Context', 'The trial''s results were ____: the drug seemed to help patients in one hospital but had no measurable effect in another, leaving researchers unsure what to conclude.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["decisive", "fabricated", "unanimous", "equivocal"]'::jsonb, 3, null, 'Results that can be read two ways are equivocal.', 'published', 'import', now()),
('rwl3e_002', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Rather than wait years for funding to build an ideal new bridge, the town council took a ____ approach, reinforcing the old one so that it could safely carry traffic for another decade.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["idealistic", "sentimental", "pragmatic", "reckless"]'::jsonb, 2, null, 'Choosing a cheaper, workable fix over a perfect one is pragmatic.', 'published', 'import', now()),
('rwl3e_003', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Many of the sand mandalas created by Tibetan Buddhist monks are deliberately ____: after weeks of painstaking work, the monks sweep the colored sand away.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["monumental", "costly", "ephemeral", "permanent"]'::jsonb, 2, null, 'Art designed to disappear quickly is ephemeral.', 'published', 'import', now()),
('rwl3e_004', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Historians were initially doubtful of the sailor''s diary, but ship records and letters from other crew members later served to ____ his account of the voyage.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["conceal", "summarize", "contradict", "corroborate"]'::jsonb, 3, null, 'Independent evidence that confirms an account corroborates it.', 'published', 'import', now()),
('rwl3e_005', 'rw', 3, 'Craft and Structure', 'Words in Context', 'City planners hope that planting thousands of shade trees will ____ the effects of summer heat waves, lowering street temperatures by several degrees.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["mitigate", "intensify", "document", "predict"]'::jsonb, 0, null, 'Reducing the harm of heat is to mitigate it.', 'published', 'import', now()),
('rwl3e_006', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Scholars can often identify the poet''s unsigned manuscripts by her ____ punctuation: she used long dashes where nearly every other writer of her time used commas.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["illegible", "idiosyncratic", "conventional", "anonymous"]'::jsonb, 1, null, 'A personal, unusual style is idiosyncratic.', 'published', 'import', now()),
('rwl3e_007', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Over twenty years, the diplomat worked patiently to cultivate relationships with leaders on both sides of the dispute, and those relationships proved crucial during the final negotiations.', null, 'As used in the text, what does the word "cultivate" most nearly mean?', '["harvest", "plow", "plant", "develop"]'::jsonb, 3, null, 'The diplomat built friendships over years, so "cultivate" means develop.', 'published', 'import', now()),
('rwl3e_008', 'rw', 3, 'Craft and Structure', 'Words in Context', 'After weeks of heated public arguments, the mayor''s speech struck a surprisingly ____ tone, praising her opponents'' concerns and inviting them to help revise the plan.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["conciliatory", "triumphant", "evasive", "defiant"]'::jsonb, 0, null, 'A tone meant to calm and make peace is conciliatory.', 'published', 'import', now()),
('rwl3e_009', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'When Phillis Wheatley, an enslaved young woman in Boston, prepared her book of poems for publication in 1773, many readers doubted that she could have written them. She was questioned by a group of prominent Boston men, who then signed a statement confirming her authorship. That statement was printed at the front of her book, which became the first published volume of poetry by an African American woman.', null, 'Which choice best states the main purpose of the text?', '["To argue that poetry should be taught in schools", "To compare two American poets", "To summarize the plot of a famous poem", "To explain how a writer''s achievement was questioned and how she responded"]'::jsonb, 3, null, 'The text describes Wheatley''s examination by doubtful officials and the attestation that let her publish.', 'published', 'import', now()),
('rwl3e_010', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'Patients who receive a placebo, such as a sugar pill, often report feeling better. Doctors have usually explained this effect as the result of expectation: patients improve because they believe they are receiving real medicine. Yet in several studies, patients who were openly told that their pills contained no medicine still reported less pain than patients who received no pills at all.', null, 'Which choice best describes the function of the third sentence in the overall structure of the text?', '["It restates the claim made in the first sentence", "It gives an example that supports the second sentence", "It describes the method used in the original studies", "It presents a finding that complicates the common explanation described earlier"]'::jsonb, 3, null, 'The third sentence shows that placebos can work even when patients know they are placebos, which challenges the idea that belief is required.', 'published', 'import', now()),
('rwl3e_011', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'In Death Valley''s Racetrack Playa, heavy rocks leave long trails across the flat, dry lakebed, as though they have slid on their own. No people or animals were ever seen moving them, and some of the rocks weigh hundreds of pounds. In 2014, researchers finally captured the process: on rare winter mornings, thin sheets of ice form on the playa, and light winds push the ice—and the rocks trapped in it—slowly across the mud.', null, 'Which choice best describes the overall structure of the text?', '["It compares two competing theories and declares both wrong", "It introduces a puzzle, rules out an obvious explanation, and then offers a more likely one", "It describes a historical event in chronological order", "It defines a scientific term and lists examples"]'::jsonb, 1, null, 'The text asks why the stones move, rejects people or animals, and then explains thin ice and wind.', 'published', 'import', now()),
('rwl3e_012', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'The following text is from a short story.

I had always thought my mother simply liked her old gray coat. She patched its elbows every winter and laughed when I teased her about it. It was only after she sent me off to college in a new wool coat of my own—one I later learned had cost nearly a month of her wages—that I understood why she had never replaced hers.', null, 'Which choice best states the main purpose of the text?', '["To compare city life and country life", "To convey the narrator''s growing awareness of how much her mother sacrificed", "To describe the narrator''s career as a seamstress", "To explain how to repair a coat"]'::jsonb, 1, null, 'The narrator realizes that her mother had been wearing the patched coat so the narrator could have a new one.', 'published', 'import', now()),
('rwl3e_013', 'rw', 3, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
Some scholars have argued that the people of Rapa Nui (Easter Island) brought about their own downfall. In this view, they cut down the island''s forests, partly to move their giant stone statues, and the resulting environmental damage led to famine and a population crash before Europeans arrived in 1722.

Text 2
Other researchers point out that rats, which arrived with the first settlers, ate the seeds of the island''s palm trees and contributed heavily to deforestation. They also argue that archaeological evidence shows the population remained fairly stable until European contact brought disease and slave raids, which caused the real catastrophe.', null, 'Based on the texts, how would the researchers described in Text 2 most likely respond to Text 1?', '["By arguing that the island''s population stayed relatively stable until contact with Europeans, contradicting the claim of a self-inflicted collapse", "By claiming that the island never had any trees", "By agreeing that the islanders cut down all their trees to move statues", "By arguing that the statues were built after Europeans arrived"]'::jsonb, 0, null, 'Text 2 attributes deforestation partly to rats and says the population collapse followed European contact.', 'published', 'import', now()),
('rwl3e_014', 'rw', 3, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
In 1993, a small study reported that college students who listened to a Mozart sonata scored higher on a spatial reasoning task than students who sat in silence. The finding, quickly nicknamed the "Mozart effect," inspired some parents to play classical music to their babies in hopes of making them smarter.

Text 2
Later attempts to repeat the study often failed. When the effect did appear, it was small and disappeared within about fifteen minutes. Researchers found that any music or activity that left participants feeling alert and in a good mood produced similar results, suggesting that there is nothing special about Mozart.', null, 'Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1?', '["By agreeing that listening to Mozart permanently raises intelligence", "By claiming that the original study used no music", "By arguing that the effect is small, brief, and likely caused by mood rather than by Mozart''s music specifically", "By arguing that only professional musicians benefit from music"]'::jsonb, 2, null, 'Text 2 says the effect is short and explained by arousal, not specifically by Mozart.', 'published', 'import', now()),
('rwl3e_015', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'In the early 1950s, programming a computer meant writing long strings of numeric codes. Computer scientist Grace Hopper believed that programs could instead be written using words close to ordinary English, which a special program called a compiler would translate for the machine. Many colleagues doubted the idea, but her work led to COBOL, a language that businesses used widely for decades.', null, 'Which choice best states the main idea of the text?', '["Hopper argued that only mathematicians should program computers", "Hopper helped make computers easier to program by letting people write instructions in words rather than numeric codes", "Hopper built the first electronic computer", "Hopper''s compiler was rejected by every company"]'::jsonb, 1, null, 'The text focuses on Hopper''s push for English-like programming languages.', 'published', 'import', now()),
('rwl3e_016', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'The following text is from a short story.

When the cast list went up, my name wasn''t next to the lead role—Lucy''s was. My throat tightened, but when Lucy turned around, her eyes huge with disbelief, I made myself smile. "You''re going to be amazing," I told her, and I hugged her before she could see my face.', null, 'Based on the text, what is true about the narrator?', '["She is openly angry at her friend", "She is glad that she was not chosen", "She did not want to be in the play", "She hides her disappointment in order to support her friend"]'::jsonb, 3, null, 'She smiles and congratulates Lucy while her own throat tightens, concealing her feelings.', 'published', 'import', now()),
('rwl3e_017', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'To learn whether gut bacteria influence weight, researchers raised mice with no bacteria in their intestines. They then gave some of these mice bacteria taken from heavier mice and others bacteria from leaner mice. Although all the mice ate the same diet, those that received bacteria from the heavier mice gained significantly more body fat.', null, 'According to the text, what did researchers find about the gut bacteria of mice?', '["Transferring bacteria from one group of mice to another also transferred a tendency to gain weight", "Bacteria have no effect on how mice digest food", "Mice without bacteria gained the most weight", "All mice have the same gut bacteria"]'::jsonb, 0, null, 'Germ-free mice given bacteria from heavier mice gained more fat than those given bacteria from leaner mice.', 'published', 'import', now()),
('rwl3e_018', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'Many stone walls built by the Inca in Peru more than five hundred years ago still stand, though the region suffers frequent earthquakes. The Inca cut stones so precisely that they fit together without mortar. During a quake, the stones can shift slightly and then settle back into place. Some modern engineers have studied these walls when designing buildings that can flex rather than crack.', null, 'Which choice best states the main idea of the text?', '["Modern buildings in Peru are made entirely of stone", "Earthquakes in Peru have destroyed every ancient wall", "Inca builders used mortar to hold their walls together", "The Inca built stone walls that survive earthquakes by shifting and settling, a design that has influenced some modern engineers"]'::jsonb, 3, null, 'The text compares Inca stonework that flexes in earthquakes with modern designs inspired by it.', 'published', 'import', now()),
('rwl3e_019', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'An economist claims that lower-income households spend a much larger share of their income on food than higher-income households do.', '{"h": ["Income group", "Average yearly food spending ($)", "Share of income spent on food (%)"], "r": [["Lowest", "5,100", "32"], ["Middle", "8,300", "15"], ["Highest", "13,900", "8"]]}'::jsonb, 'Which choice most effectively uses data from the table to support the economist''s claim?', '["There were three income groups in the survey", "Households in the highest income group spent the most money on food overall", "Households in the lowest income group spent 32 percent of their income on food, compared with 8 percent for the highest income group", "Households in the middle income group spent 15 percent of their income on food"]'::jsonb, 2, null, 'The claim concerns share of income; this choice compares the lowest and highest shares directly.', 'published', 'import', now()),
('rwl3e_020', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'In an essay, a historian describes how her research gradually made her doubt the accuracy of the sources she had initially trusted.', null, 'Which quotation from the essay most effectively illustrates the claim?', '["\"The archive''s maps were stored in long, flat drawers.\"", "\"I first visited the archive in the autumn of 2010.\"", "\"The longer I studied the old maps, the less certain I became that any of them showed the coast as it truly was.\"", "\"The oldest map in the collection dates from 1590.\""]'::jsonb, 2, null, 'Growing doubt as study continues is the change in perspective the claim describes.', 'published', 'import', now()),
('rwl3e_021', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'Researchers hypothesize that ravens can take into account what other ravens might be able to see when deciding how to hide food.', null, 'Which finding, if true, would most directly support the researchers'' hypothesis?', '["Ravens prefer meat to seeds when given a choice", "Ravens that had watched a researcher hide food behind a barrier took more care to conceal their own food when a peephole in the barrier was open", "Ravens can recognize the calls of other ravens", "Ravens hide food more often in winter than in summer"]'::jsonb, 1, null, 'Hiding food more carefully when they might be watched shows ravens consider what others can see.', 'published', 'import', now()),
('rwl3e_022', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'A historian claims that a distinctive weaving pattern spread through a region''s villages in the 1830s because traveling textile merchants introduced it.', null, 'Which finding, if true, would most directly weaken the historian''s claim?', '["Many villagers wove cloth for their own families", "Letters from the 1820s describe the same weaving pattern being used in villages that had no contact with the textile merchants", "The textile merchants sold cloth in several cities", "The weaving pattern became popular in the 1840s"]'::jsonb, 1, null, 'If villages without contact already used the pattern, the merchants likely didn''t introduce it.', 'published', 'import', now()),
('rwl3e_023', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'After a new waterfront park opened near a bridge in 2024, city officials noticed that the park seemed to affect weekend traffic far more than weekday traffic. Indeed, the table shows that ____', '{"h": ["Day type", "Average vehicles, 2023", "Average vehicles, 2025"], "r": [["Weekday", "11,400", "12,000"], ["Weekend", "4,200", "9,100"]]}'::jsonb, 'Which choice most effectively uses data from the table to complete the statement?', '["the bridge''s traffic increased only slightly on weekdays but more than doubled on weekends", "the bridge carried 12,000 vehicles on an average weekday in 2025", "weekday traffic was greater than weekend traffic in 2023", "the bridge was open both on weekdays and on weekends"]'::jsonb, 0, null, 'This is the only choice that compares the change on weekdays with the change on weekends.', 'published', 'import', now()),
('rwl3e_024', 'rw', 3, 'Information and Ideas', 'Inferences', 'Fragments of purple cloth found at an inland village site were colored with a dye made from a sea snail that lives only along the Mediterranean coast, hundreds of kilometers away. No snail shells or dye-making tools were found at the site. These findings suggest that ____', null, 'Which choice most logically completes the text?', '["purple dye was common in every ancient village", "the village''s weavers invented the dye themselves", "the dye was likely obtained through trade rather than made locally", "the cloth was made after the village was abandoned"]'::jsonb, 2, null, 'The dye came from a sea snail found only far away, so the village probably traded for it.', 'published', 'import', now()),
('rwl3e_025', 'rw', 3, 'Information and Ideas', 'Inferences', 'Over thirty years, average spring temperatures in a forest rose by nearly 2°C. Many plant species there now leaf out earlier than they once did. Beech trees, however, have continued to leaf out within a few days of the same date each year. Because day length in spring has not changed, researchers suggest that ____', null, 'Which choice most logically completes the text?', '["the trees'' leaf-out date may depend more on day length than on temperature", "temperature is the only factor controlling when trees grow leaves", "the trees leaf out only in unusually warm years", "the trees stopped growing leaves during the study"]'::jsonb, 0, null, 'Leaf-out stayed about the same despite warmer springs, so temperature may not control it.', 'published', 'import', now()),
('rwl3e_026', 'rw', 3, 'Information and Ideas', 'Inferences', 'A company points out that children in a town had 30 percent fewer cavities in the two years after its new toothpaste went on sale there. But during the same two years, the town also began adding fluoride to its drinking water, a change known to reduce cavities. Therefore, ____', null, 'Which choice most logically completes the text?', '["the new toothpaste caused all the improvement", "the reduction in cavities is unlikely to have been caused by the new toothpaste alone", "fluoride has no effect on cavities", "the students stopped brushing their teeth"]'::jsonb, 1, null, 'The town also added fluoride to the water at the same time, so the toothpaste can''t be credited alone.', 'published', 'import', now()),
('rwl3e_027', 'rw', 3, 'Information and Ideas', 'Inferences', 'At an ancient site, archaeologists found a building whose floor was covered by a thick layer of volcanic ash. Beneath the ash, on the floor itself, lay coins minted in the year 79 CE. Based on this evidence, archaeologists concluded that ____', null, 'Which choice most logically completes the text?', '["the eruption must have occurred after the building was completed", "the building was made from volcanic ash", "the ash layer is older than the oldest coins", "the eruption happened before the building was built"]'::jsonb, 0, null, 'Coins from 79 CE lie beneath the ash, so the ash fell after they were dropped.', 'published', 'import', now()),
('rwl3e_028', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The ____ had predicted the recession years before it began—was invited to advise the national bank.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["economist who", "economist, who", "economist; who", "economist—who"]'::jsonb, 3, null, 'The interruption ends with a dash, so it must begin with one.', 'published', 'import', now()),
('rwl3e_029', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The satellite''s camera failed after only two months of collecting ____ the images it captured transformed scientists'' understanding of the comet.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["data, nevertheless,", "data nevertheless,", "data, nevertheless", "data; nevertheless,"]'::jsonb, 3, null, '"Nevertheless" joins two complete sentences, so a semicolon comes before it and a comma after.', 'published', 'import', now()),
('rwl3e_030', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The discovery of several thousand-year-old fishhooks on the island ____ that people had arrived there far earlier than once believed.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["proved:", "proved—", "proved", "proved,"]'::jsonb, 2, null, 'No punctuation belongs between the verb "proved" and the clause that is its object.', 'published', 'import', now()),
('rwl3e_031', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The artist''s work is held in only three ____ the Tate in London, the Museum of Modern Art in New York, and the National Gallery of Australia.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["museums", "museums:", "museums,", "museums, and"]'::jsonb, 1, null, 'A colon after a complete sentence introduces the list that explains "three museums."', 'published', 'import', now()),
('rwl3e_032', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'In the dry grasslands of northern ____ Grevy''s zebra survives in fewer than three thousand individuals.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Kenya. The", "Kenya, the", "Kenya; the", "Kenya the"]'::jsonb, 1, null, 'The introductory phrase "In the dry grasslands of northern Kenya" is followed by a comma.', 'published', 'import', now()),
('rwl3e_033', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'Visitors to the late ____ studio can still see half-finished canvases leaning against the walls, just as she left them.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["artists''", "artists", "artist''s", "artist"]'::jsonb, 2, null, 'The studio belongs to one artist, so the singular possessive is needed; the sentence otherwise needs no punctuation.', 'published', 'import', now()),
('rwl3e_034', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'A set of bronze tools, along with several fragments of pottery and a small carved figure, ____ uncovered beneath the floor of the ancient house.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["have been", "were", "was", "are"]'::jsonb, 2, null, 'The subject is the singular "set," not "tools," so "was" is correct.', 'published', 'import', now()),
('rwl3e_035', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'The expedition included twelve scientists, three of ____ had never before traveled to Antarctica.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["whom", "whose", "which", "who"]'::jsonb, 0, null, 'The pronoun is the object of "of," so "whom" is correct.', 'published', 'import', now()),
('rwl3e_036', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'If the explorers had carried more food, they ____ the coast before winter set in.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["would have reached", "will reach", "reached", "has reached"]'::jsonb, 0, null, 'The "if" clause describes a past situation that did not happen, so "would have reached" is needed.', 'published', 'import', now()),
('rwl3e_037', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'Unrolling the scroll with great care, ____', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["the fragile manuscript surprised the archaeologist with its condition.", "the condition of the fragile manuscript surprised the archaeologist.", "the archaeologist was surprised by the condition of the fragile manuscript.", "surprise was felt by the archaeologist at the manuscript''s condition."]'::jsonb, 2, null, 'The opening phrase describes the person who unrolled the scroll, so "the archaeologist" must come right after it.', 'published', 'import', now()),
('rwl3e_038', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'Neither the coach nor the players wanted to change ____ strategy before the championship game.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["one''s", "their", "his or her", "its"]'::jsonb, 1, null, '"Neither the coach nor the players": the pronoun agrees with the nearer noun, "players," so "their" is correct.', 'published', 'import', now()),
('rwl3e_039', 'rw', 3, 'Expression of Ideas', 'Transitions', 'Adding salt to water raises the temperature at which the water boils. ____ adding salt to water lowers the temperature at which it freezes, which is why salt is spread on icy roads.', null, 'Which choice completes the text with the most logical transition?', '["Likewise,", "Accordingly,", "For example,", "Conversely,"]'::jsonb, 3, null, 'The second sentence describes the opposite effect.', 'published', 'import', now()),
('rwl3e_040', 'rw', 3, 'Expression of Ideas', 'Transitions', 'The medieval traveler''s book contains many obvious errors, including descriptions of people with the heads of dogs. ____ historians value it as a record of what Europeans of the time believed about distant lands.', null, 'Which choice completes the text with the most logical transition?', '["Even so,", "As a result,", "In addition,", "Similarly,"]'::jsonb, 0, null, 'Scholars still study the book despite its errors, so a concession fits.', 'published', 'import', now()),
('rwl3e_041', 'rw', 3, 'Expression of Ideas', 'Transitions', 'The new study found that the medication helped some patients more than others. ____ patients under the age of forty improved twice as much as older patients.', null, 'Which choice completes the text with the most logical transition?', '["Specifically,", "Meanwhile,", "Nevertheless,", "Regardless,"]'::jsonb, 0, null, 'The second sentence gives the precise details of the general claim.', 'published', 'import', now()),
('rwl3e_042', 'rw', 3, 'Expression of Ideas', 'Transitions', 'In 1796, Edward Jenner showed that exposing people to cowpox, a mild disease, could protect them from deadly smallpox. ____ other scientists applied the same idea to develop vaccines against diseases such as rabies and cholera.', null, 'Which choice completes the text with the most logical transition?', '["Conversely,", "For instance,", "Subsequently,", "Similarly,"]'::jsonb, 2, null, 'The second event follows the first in time.', 'published', 'import', now()),
('rwl3e_043', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• A "whale fall" occurs when a whale''s body sinks to the deep seafloor.
• Researchers studied whale falls off the coast of California.
• They found that a single whale fall can support hundreds of species.
• These communities can last for decades.
• They include Osedax worms, which feed on bones.', null, 'The student wants to present the study''s findings to an audience familiar with the deep sea. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Whale falls occur when a whale''s body sinks to the seafloor.", "Researchers found that whale falls can support hundreds of species for decades, including bone-eating Osedax worms.", "The deep sea is dark and cold.", "Researchers studied whale falls off the coast of California."]'::jsonb, 1, null, 'This audience already knows what whale falls are, so the best choice goes straight to what the study found.', 'published', 'import', now()),
('rwl3e_044', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Archaeologists use several methods to date artifacts.
• Radiocarbon dating was developed in the late 1940s.
• It measures the decay of carbon in once-living material, such as wood or bone.
• Thermoluminescence dating measures energy stored in objects that were heated.
• It is often used on pottery.', null, 'The student wants to contrast the two methods of dating artifacts. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Thermoluminescence dating can be used on pottery.", "Both methods are used by archaeologists.", "Radiocarbon dating was developed in the late 1940s.", "While radiocarbon dating measures decay in once-living material such as wood or bone, thermoluminescence dating measures energy stored in heated objects such as pottery."]'::jsonb, 3, null, 'Only this choice explains how the two methods differ.', 'published', 'import', now()),
('rwl3e_045', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The Wampanoag are a Native American people of present-day Massachusetts.
• The last fluent speakers of the Wampanoag language died in the 1800s.
• The language went unspoken for more than 150 years.
• In 1993, Jessie Little Doe Baird began a project to revive it using old written documents.
• Children in the community now learn the language.', null, 'The student wants to emphasize how long the language was nearly lost. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Jessie Little Doe Baird founded a project to revive the language.", "After its last fluent speakers died in the 1800s, the Wampanoag language went unspoken for more than 150 years before revival efforts began.", "Children in the community now learn the language in school.", "The Wampanoag are a Native American people of present-day Massachusetts."]'::jsonb, 1, null, 'Only this choice stresses the long period during which the language was not spoken.', 'published', 'import', now()),
('rwl3e_046', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Mauna Kea is a dormant volcano in Hawaii.
• Its summit is more than 13,000 feet above sea level.
• The summit is above most clouds.
• The air there is dry and still, and it is far from city lights.
• More than a dozen telescopes stand on the summit.', null, 'The student wants to explain why telescopes were built on Mauna Kea. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Astronomers chose Mauna Kea''s summit because it rises above most clouds and has dry, still air far from city lights.", "Mauna Kea is a dormant volcano in Hawaii.", "Mauna Kea''s summit is more than 13,000 feet above sea level.", "More than a dozen telescopes stand on Mauna Kea."]'::jsonb, 0, null, 'Only this choice explains why the location suits telescopes.', 'published', 'import', now())
on conflict (id) do nothing;
